from fractions import Fraction

def quotient(case, a, m, n):
    e = m - n
    if a < 0:
        base = f"({a})"
    else:
        base = f"{a}"
    print(f"Case {case}: {base}**{m} / {base}**{n}")
    print(f"  same base, subtract exponents: {m} - {n} = {e}")
    value = Fraction(1)
    if e > 0:
        for k in range(e):
            value = value * a
        print(f"  {e} factors of {base}: {value}")
    elif e == 0:
        print(f"  no factors left, the empty product: {value}")
    else:
        for k in range(-e):
            value = value / a
        print(f"  1 divided by {base}, {-e} times: {value}")
    print(f"  check: {Fraction(a) ** m / Fraction(a) ** n}")

quotient("1 · more on top", 5, 7, 4)
quotient("2 · equal exponents", 7, 4, 4)
quotient("3 · more on the bottom", 3, 2, 5)
quotient("4 · a negative base", -2, 1, 4)
quotient("5 · a zero exponent on top", 10, 0, 3)

