from fractions import Fraction
n_problems = int(input())
for k in range(n_problems):
    a = int(input())
    m = int(input())
    n = int(input())
    if a < 0:
        base = f"({a})"
    else:
        base = f"{a}"
    e = m - n
    value = Fraction(1)
    if e > 0:
        for j in range(e):
            value = value * a
    elif e < 0:
        for j in range(-e):
            value = value / a
    print(f"{base}**{m} / {base}**{n} = {base}**{e} = {value}")
